use std::fs

struct Tree {
    keys: Vec<int>,
    l: Vec<int>,
    r: Vec<int>,
    root: int,
}

impl Tree {
    fn contains(self, x: int) -> bool {
        let mut cur = self.root
        while cur != -1 {
            let k = self.keys[cur as usize]
            if x == k { return true }
            if x < k { cur = self.l[cur as usize] } else { cur = self.r[cur as usize] }
        }
        false
    }

    fn insert(self, x: int) {
        let id = self.keys.len() as int
        self.keys.push(x)
        self.l.push(-1)
        self.r.push(-1)
        if self.root == -1 {
            self.root = id
            return
        }
        let mut cur = self.root
        loop {
            let k = self.keys[cur as usize]
            if x < k {
                if self.l[cur as usize] == -1 {
                    self.l[cur as usize] = id
                    return
                }
                cur = self.l[cur as usize]
            } else {
                if self.r[cur as usize] == -1 {
                    self.r[cur as usize] = id
                    return
                }
                cur = self.r[cur as usize]
            }
        }
    }

    fn del(self, node: int, x: int) -> int {
        if node == -1 { return -1 }
        let n = node as usize
        let k = self.keys[n]
        if x < k {
            let c = self.l[n]
            let nc = self.del(c, x)
            self.l[n] = nc
            return node
        }
        if x > k {
            let c = self.r[n]
            let nc = self.del(c, x)
            self.r[n] = nc
            return node
        }
        if self.l[n] == -1 { return self.r[n] }
        if self.r[n] == -1 { return self.l[n] }
        let mut s = self.r[n]
        while self.l[s as usize] != -1 { s = self.l[s as usize] }
        let sk = self.keys[s as usize]
        self.keys[n] = sk
        let c = self.r[n]
        let nc = self.del(c, sk)
        self.r[n] = nc
        node
    }

    fn height(self, node: int) -> int {
        if node == -1 { return 0 }
        let a = self.height(self.l[node as usize])
        let b = self.height(self.r[node as usize])
        if a > b { a + 1 } else { b + 1 }
    }

    fn inorder(self) -> string {
        let mut out: Vec<string> = []
        let mut stack: Vec<int> = []
        let mut cur = self.root
        while cur != -1 || stack.len() > 0 {
            while cur != -1 {
                stack.push(cur)
                cur = self.l[cur as usize]
            }
            let t = stack.pop() ?? 0
            out.push("${self.keys[t as usize]}")
            cur = self.r[t as usize]
        }
        out.join(" ")
    }
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut t = Tree { keys: [], l: [], r: [], root: -1 }
    for line in text.lines() {
        let mut parts: Vec<string> = []
        for p in line.split_whitespace() { parts.push(p.to_string()) }
        if parts.len() == 0 { continue }
        let cmd = parts[0]
        if cmd == "insert" {
            let x: int = parts[1].parse() ?? 0
            if t.contains(x) { println("dup") } else {
                t.insert(x)
                println("ok")
            }
        } else if cmd == "contains" {
            let x: int = parts[1].parse() ?? 0
            if t.contains(x) { println("yes") } else { println("no") }
        } else if cmd == "delete" {
            let x: int = parts[1].parse() ?? 0
            if t.contains(x) {
                let rt = t.root
                t.root = t.del(rt, x)
                println("ok")
            } else { println("missing") }
        } else if cmd == "inorder" {
            if t.root == -1 { println("<empty>") } else { println(t.inorder()) }
        } else if cmd == "height" {
            println("${t.height(t.root)}")
        } else if cmd == "min" {
            if t.root == -1 { println("empty") } else {
                let mut c = t.root
                while t.l[c as usize] != -1 { c = t.l[c as usize] }
                println("${t.keys[c as usize]}")
            }
        } else if cmd == "max" {
            if t.root == -1 { println("empty") } else {
                let mut c = t.root
                while t.r[c as usize] != -1 { c = t.r[c as usize] }
                println("${t.keys[c as usize]}")
            }
        }
    }
}

